'use strict';
const test=require('node:test'); const assert=require('node:assert/strict'); const fsp=require('node:fs/promises'); const fs=require('node:fs'); const os=require('node:os'); const path=require('node:path'); const zlib=require('node:zlib'); const {createLocalDb}=require('../server/lib/local-db'); const {createSyncSettings}=require('../server/lib/sync-settings'); const {buildSyncPackages,validateSyncPackage,SYNC_PACKAGE_DIR,SYNC_GZIP_SUFFIX,isBundleFile}=require('../server/lib/sync-package');
async function tmp(t,p){const root=await fsp.mkdtemp(path.join(os.tmpdir(),p));t.after(()=>fsp.rm(root,{recursive:true,force:true}));return root;} function droot(shared,db){return path.join(shared,'BUYER_LOG_SYNC','changes',encodeURIComponent(db.getDeviceId()));} async function advertise(sync){await sync.syncOnce();} async function readBundle(file){const b=await fsp.readFile(file);return JSON.parse((String(file).endsWith(SYNC_GZIP_SUFFIX)?zlib.gunzipSync(b):b).toString('utf8'));}
test('bundle checksum/event checksum corruption is rejected before apply',async t=>{const root=await tmp(t,'bl-corruption-'),db=createLocalDb(path.join(root,'d','BuyerLogLocal.db'));await db.ensure();await db.queuePatch({id:'A',patch:{v:1}});const pkg=buildSyncPackages(await db.pending(10),{deviceId:db.getDeviceId()}).packages[0].manifest;const corrupt=JSON.parse(JSON.stringify(pkg));corrupt.events[0].patch.v=999;assert.throws(()=>validateSyncPackage(corrupt),/checksum/i);});
